46	/**
47	 * One step of Rule 30 applied to a whole row at once.
48	 *
49	 * Rule 30 is  new = left XOR (center OR right).  The only trick is getting the
50	 * two shifts the right way round, which is genuinely easy to invert, so here is
51	 * the reasoning spelled out:
52	 *
53	 *   Bit i of `x << 1n` is bit i-1 of `x`. Bit i-1 is cell i's LEFT neighbour.
54	 *   Therefore `x << 1n` is the whole "left neighbour" plane, aligned so that
55	 *   position i holds what cell i needs.
56	 *
57	 *   Bit i of `x >> 1n` is bit i+1 of `x`, which is cell i's RIGHT neighbour.
58	 *   Therefore `x >> 1n` is the "right neighbour" plane, likewise aligned.
59	 *
60	 * Read it as: shifting a value UP moves each cell's contents rightward into a
61	 * higher index, so what lands at index i is what used to sit at i-1, on the
62	 * left. The shift direction is opposite to the direction the data appears to
63	 * move when you draw the row with low indices on the left.
64	 *
65	 * With all three planes aligned at index i, the rule applies to every cell
66	 * simultaneously:
67	 *
68	 *     next = (x << 1n) ^ (x | (x >> 1n))
69	 *              left        center  right
70	 *
71	 * `x` must be non-negative. BigInt `>>` is an arithmetic shift, so a negative
72	 * row would sign-extend forever; every row produced here is non-negative.
73	 *
74	 * @param {bigint} x row as a bit-per-cell BigInt
75	 * @returns {bigint} the next row
76	 */
77	export function step(x) {
78	  return (x << 1n) ^ (x | (x >> 1n));
79	}
80	
81	/**
82	 * Bit index of the center column for a run of `generations` generations.
83	 *
84	 * The pattern grows by exactly one cell in each direction per step, so after
85	 * `generations - 1` steps it occupies indices center +/- (generations - 1). The
86	 * center cell itself never moves. Bits below index 0 do not exist, so the
87	 * initial cell is placed high enough that the leftward growth never runs off
88	 * the bottom: `generations + 2` gives that headroom with two bits to spare.
89	 * Rightward growth needs no headroom at all, since a BigInt has no ceiling.
90	 *
91	 * @param {number} generations
92	 * @returns {number}
93	 */
94	export function centerBitIndex(generations) {
95	  return generations + 2;
96	}
97	
98	/**
99	 * The initial configuration: a single black cell on a white background.
100	 *
101	 * @param {number} generations how many generations the run will cover
102	 * @returns {bigint}
103	 */
104	export function initialRow(generations) {
105	  return 1n << BigInt(centerBitIndex(generations));
106	}
