108	/**
109	 * Every row of the evolution, starting from a single black cell.
110	 *
111	 * Yields `generations` rows. The first is the initial configuration, before any
112	 * step. Each row is a BigInt whose bit `centerBitIndex(generations)` is the
113	 * center column.
114	 *
115	 * @param {number} generations
116	 * @yields {bigint}
117	 */
118	export function* rows(generations) {
119	  assertGenerations(generations);
120	  let x = initialRow(generations);
121	  for (let g = 0; g < generations; g++) {
122	    yield x;
123	    x = step(x);
124	  }
125	}
