127	/**
128	 * The center column, as a sequence of 0s and 1s.
129	 *
130	 * Yields `generations` terms; term 0 is the initial lone black cell, so the
131	 * sequence starts 1, 1, 0, 1, 1, 1, 0, 0, ... (A051023).
132	 *
133	 * ## Two things this does that `rows` does not
134	 *
135	 * Both are about keeping the BigInt no bigger than the live pattern, because
136	 * every bitwise operation costs time proportional to the *whole* BigInt — dead
137	 * zero bits included.
138	 *
139	 * **1. It slides the window instead of reserving space up front.**
140	 * `rows` parks the initial cell at a fixed high bit so leftward growth never
141	 * runs off bit 0. That means the row carries a block of zeros below the
142	 * pattern for the entire run, and those zeros are stored and processed like any
143	 * other bits. Here the initial cell sits just `PAD` bits above the bottom
144	 * instead, and every `PAD` generations — when the pattern has eaten through the
145	 * padding — the row is shifted up to restore it. One shift per `PAD` steps is
146	 * nothing; carrying N dead bits for N steps is most of the run.
147	 *
148	 * The step itself does not drift: the cell at bit i stays at bit i, so shifting
149	 * up is bookkeeping about where bit 0 is, not a correction.
150	 *
151	 * **2. It discards cells that can no longer reach the center (`trim`).**
152	 * Information travels one cell per step, so the center cell at generation N-1
153	 * can only be affected by cells within distance N-1-g at generation g.
154	 * Anything further out never arrives in time. Past the halfway mark that light
155	 * cone is narrower than the pattern, and the row can be masked down to it — and
156	 * then shifted back down, since the mask leaves a fresh block of dead low bits
157	 * behind. Together with the sliding window this takes the total bit-work from
158	 * about 1.5*N^2 to about 0.5*N^2.
159	 *
160	 * The mask is rebuilt only every `TRIM_INTERVAL` generations, because building
161	 * it costs a pass over the row too. Between rebuilds the row regrows a little
162	 * garbage outside the cone, which is harmless precisely because it is outside
163	 * the cone: the correct region shrinks by one cell per step, and so does the
164	 * region we still need.
165	 *
166	 * Set `trim: false` to keep every cell. The two modes must agree on every term,
167	 * and explorer/verify.mjs checks that they do.
168	 *
169	 * @param {number} generations
170	 * @param {{trim?: boolean}} [options]
171	 * @yields {0|1}
172	 */
173	export function* centerColumn(generations, { trim = true } = {}) {
174	  assertGenerations(generations);
175	
176	  const last = generations - 1;
177	
178	  // `pad` is how many zero bits sit below the pattern's leftmost cell; it drops
179	  // by one per step. `center` is the bit index of the center cell right now.
180	  let pad = PAD;
181	  let center = BigInt(PAD);
182	  let x = 1n << center;
183	
184	  for (let g = 0; g < generations; g++) {
185	    yield Number((x >> center) & 1n);
186	
187	    if (g === last) return;
188	    x = step(x);
189	
190	    if (--pad === 0) {
191	      // The pattern's leftmost cell is now at bit 0. One more step would need
192	      // bit -1, which does not exist, so make room.
193	      x <<= PAD_BIG;
194	      center += PAD_BIG;
195	      pad = PAD;
196	    }
197	
198	    const gen = g + 1;
199	    if (trim && gen % TRIM_INTERVAL === 0) {
200	      const radius = last - gen;
201	      // Only worth doing once the light cone is narrower than the pattern's own
202	      // half-width, which is `gen`.
203	      if (radius < gen) {
204	        x &= lightConeMask(center, radius);
205	        // Masking left `center - radius` dead bits at the bottom. Drop all but
206	        // PAD of them, and move the center index down to match.
207	        const shift = Number(center) - radius - PAD;
208	        if (shift > 0) {
209	          x >>= BigInt(shift);
210	          center -= BigInt(shift);
211	          pad = PAD;
212	        }
213	      }
214	    }
215	  }
216	}
