218	/** Zero bits kept below the pattern, and how often they are replenished. */
219	const PAD = 512;
220	const PAD_BIG = BigInt(PAD);
221	
222	/** How often `centerColumn` rebuilds the light-cone mask. */
223	const TRIM_INTERVAL = 4096;
224	
225	/**
226	 * A run of `2 * radius + 1` set bits centered on bit `center`.
227	 *
228	 * @param {bigint} center
229	 * @param {number} radius
230	 * @returns {bigint}
231	 */
232	function lightConeMask(center, radius) {
233	  const r = BigInt(radius);
234	  return ((1n << (2n * r + 1n)) - 1n) << (center - r);
235	}
