258	/**
259	 * Render one row as text, `radius` cells either side of the center.
260	 *
261	 * @param {bigint} row
262	 * @param {number} generations the value passed to `rows`, which fixes the center
263	 * @param {number} radius
264	 * @param {[string, string]} [glyphs] characters for 0 and 1
265	 * @returns {string}
266	 */
267	export function renderRow(row, generations, radius, glyphs = [' ', '#']) {
268	  const center = centerBitIndex(generations);
269	  let s = '';
270	  for (let i = center - radius; i <= center + radius; i++) {
271	    s += i < 0 ? glyphs[0] : glyphs[Number((row >> BigInt(i)) & 1n)];
272	  }
273	  return s;
274	}
