280	/**
281	 * A rule number *is* its lookup table.
282	 *
283	 * An elementary cellular automaton looks at three cells — left, center, right.
284	 * Three binary cells give 2^3 = 8 possible neighbourhoods. The rule has to say
285	 * what each of those 8 produces, and each answer is a single bit. Eight bits is
286	 * one byte, so the complete specification of an elementary rule is exactly one
287	 * number in 0..255, and there are exactly 256 such automata.
288	 *
289	 * Wolfram's numbering reads the neighbourhood as a 3-bit binary number with the
290	 * left cell most significant:
291	 *
292	 *     index = 4*left + 2*center + 1*right
293	 *
294	 * and the rule's output for that neighbourhood is bit `index` of the rule byte.
295	 * So rule 30 = 0b00011110:
296	 *
297	 *     neighbourhood  index  bit of 30  output
298	 *     111            7      0          0
299	 *     110            6      0          0
300	 *     101            5      0          0
301	 *     100            4      1          1
302	 *     011            3      1          1
303	 *     010            2      1          1
304	 *     001            1      1          1
305	 *     000            0      0          0
306	 *
307	 * which is the same function as `left XOR (center OR right)` — check the 100
308	 * and 011 lines against it. The BigInt engine hard-codes that XOR/OR form; this
309	 * side derives the table from the number instead, so the two agree only if both
310	 * are right.
311	 *
312	 * @param {number} rule 0..255
313	 * @returns {Uint8Array} 8 entries, indexed by 4*left + 2*center + 1*right
314	 */
315	export function ruleTable(rule) {
316	  if (!Number.isInteger(rule) || rule < 0 || rule > 255) {
317	    throw new RangeError(`rule must be an integer in 0..255, got ${rule}`);
318	  }
319	  const table = new Uint8Array(8);
320	  for (let index = 0; index < 8; index++) {
321	    table[index] = (rule >> index) & 1;
322	  }
323	  return table;
324	}
325	
326	/**
327	 * One naive step: read three cells, look the neighbourhood up, write one cell.
328	 *
329	 * Cells outside the array are treated as 0, which is the white background.
330	 *
331	 * @param {Uint8Array} cells
332	 * @param {Uint8Array} table from `ruleTable`
333	 * @param {Uint8Array} [out] scratch buffer of the same length
334	 * @returns {Uint8Array}
335	 */
336	export function naiveStep(cells, table, out = new Uint8Array(cells.length)) {
337	  const n = cells.length;
338	  for (let i = 0; i < n; i++) {
339	    const left = i > 0 ? cells[i - 1] : 0;
340	    const center = cells[i];
341	    const right = i < n - 1 ? cells[i + 1] : 0;
342	    out[i] = table[(left << 2) | (center << 1) | right];
343	  }
344	  return out;
345	}
346	
347	/**
348	 * The center column of any elementary rule, computed cell by cell.
349	 *
350	 * Deliberately slow and deliberately unclever: this is the control, so it must
351	 * not share any reasoning with the BigInt engine. Cost is O(generations^2).
352	 *
353	 * The buffer uses the same indexing as the BigInt row — slot i is cell i, with
354	 * the initial cell at `centerBitIndex(generations)` — so rows from the two
355	 * implementations line up without translation.
356	 *
357	 * @param {number} rule 0..255
358	 * @param {number} generations
359	 * @returns {Uint8Array} `generations` terms, 0 or 1
360	 */
361	export function naiveCenterColumn(rule, generations) {
362	  assertGenerations(generations);
363	  const table = ruleTable(rule);
364	  const center = centerBitIndex(generations);
365	  const width = center + generations + 2;
366	
367	  let cells = new Uint8Array(width);
368	  let scratch = new Uint8Array(width);
369	  cells[center] = 1;
370	
371	  const out = new Uint8Array(generations);
372	  for (let g = 0; g < generations; g++) {
373	    out[g] = cells[center];
374	    const next = naiveStep(cells, table, scratch);
375	    scratch = cells;
376	    cells = next;
377	  }
378	  return out;
379	}
380	
381	/**
382	 * Full rows from the naive implementation, as BigInts using the same bit
383	 * layout as `rows`. Used by verify.mjs to compare entire rows rather than only
384	 * the center column.
385	 *
386	 * @param {number} rule 0..255
387	 * @param {number} generations
388	 * @yields {bigint}
389	 */
390	export function* naiveRows(rule, generations) {
391	  assertGenerations(generations);
392	  const table = ruleTable(rule);
393	  const center = centerBitIndex(generations);
394	  const width = center + generations + 2;
395	
396	  let cells = new Uint8Array(width);
397	  let scratch = new Uint8Array(width);
398	  cells[center] = 1;
399	
400	  for (let g = 0; g < generations; g++) {
401	    let row = 0n;
402	    for (let i = width - 1; i >= 0; i--) row = (row << 1n) | BigInt(cells[i]);
403	    yield row;
404	    const next = naiveStep(cells, table, scratch);
405	    scratch = cells;
406	    cells = next;
407	  }
408	}
409	
410	// ---------------------------------------------------------------------------
411	
412	function assertGenerations(generations) {
413	  if (!Number.isInteger(generations) || generations < 1) {
414	    throw new RangeError(
415	      `generations must be a positive integer, got ${generations}`,
416	    );
417	  }
418	}
